sysevent_in_email_action.script:
(function runAction( /*GlideRecord*/ current, /*GlideRecord*/ event, /*EmailWrapper*/ email, /*ScopedEmailLogger*/ logger, /*EmailClassifier*/ classifier) {

    var DEFAULT_CATEGORY = 'inquiry';   
    var DEFAULT_LEVEL = '3';           

    var categories = ["hardware", "software", "database", "network"];
    var urgencyAndImpactMap = {
        1: ['high', 'highest', 'maximum', 'higher', 'critical', '1 - high', '1-high'],
        2: ['medium', 'moderate', 'average', '2-moderate', '2 - moderate'],
        3: ['low', 'lower', 'fewer', 'minimum', '3-low', '3 - low']
    };

    var shortDescription = (email.subject || '').trim();
    var description = email.body_text || '';
    var lines = description.split('\n');

    var levelLookup = {};
    for (var lvl in urgencyAndImpactMap) {
        levelLookup[lvl] = lvl;
        urgencyAndImpactMap[lvl].forEach(function(word) {
            levelLookup[word] = lvl;
        });
    }

    function readLine(label) {
        for (var i = 0; i < lines.length; i++) {
            var text = lines[i].trim().toLowerCase();
            if (text.indexOf(label) != 0) continue;
            var rest = text.substring(label.length).trim();
            var sep = rest.charAt(0);
            if (sep == ':' || sep == '-' || sep == '=')
                return rest.substring(1).split(' ').filter(function(w) { return w; }).join(' ');
        }
        return '';
    }

    function toLevel(value) {
        return levelLookup[value] || levelLookup[value.split(' ')[0]] || '';
    }

    // ---------- caller ----------
    var callerId = '';
    var u = new GlideRecord('sys_user');
    u.addQuery('email', email.origemail);
    u.addActiveQuery();
    u.setLimit(1);
    u.query();
    if (u.next()) callerId = u.getUniqueValue();

    // ---------- category / impact / urgency ----------
    var category = readLine('category').split(' ')[0];
    if (categories.indexOf(category) == -1)
        category = DEFAULT_CATEGORY;

    var impact = toLevel(readLine('impact')) || DEFAULT_LEVEL;
    var urgency = toLevel(readLine('urgency')) || DEFAULT_LEVEL;

    // Unknown senders can't self-declare High (delete this block if you don't want the cap)
    if (!callerId) {
        if (impact == '1') impact = '2';
        if (urgency == '1') urgency = '2';
    }

    // ---------- create the incident ----------
    current.short_description = shortDescription;
    current.description = description;
    current.contact_type = 'email';
    current.category = category;
    current.impact = impact;
    current.urgency = urgency;
    if (callerId) current.caller_id = callerId;

    current.insert();

})(current, event, email, logger, classifier);
